// writeLegacyPackage builds, by hand, the on-disk layout vmono made before
// sessions: a schema 1 manifest holding the branch, a worktree per member at
// the package root, generated files beside them, and a package repo that
// tracks them. It does not use the current code to make it, so the test
// does not just mirror the migration. It returns the package directory.
func writeLegacyPackage(t *testing.T, c *Core, name, branch string, active, refs []string) string {
	t.Helper()
	root, err := c.PackageRoot()
	if err != nil {
		t.Fatal(err)
	}
	dir := filepath.Join(root, name)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	var b strings.Builder
	fmt.Fprintf(&b, "schema  = 1\nname    = %q\ncreated = 2026-11-01T10:00:00Z\nbranch  = %q\n\npurpose = \"Legacy purpose.\"\n", name, branch)
	var ignore strings.Builder
	for _, src := range active {
		mem := filepath.Base(src)
		fmt.Fprintf(&b, "\n[[member]]\nname   = %q\nsource = %q\nmode   = \"active\"\npath   = %q\nbase   = \"origin/HEAD\"\nrole   = \"legacy role\"\n", mem, src, mem)
		testutil.Git(t, src, "worktree", "add", "-q", "-b", branch, filepath.Join(dir, mem), "origin/HEAD")
		fmt.Fprintf(&ignore, "/%s/\n", mem)
	}
	for _, src := range refs {
		mem := filepath.Base(src)
		fmt.Fprintf(&b, "\n[[member]]\nname   = %q\nsource = %q\nmode   = \"reference\"\npath   = %q\nref    = \"origin/HEAD\"\n", mem, src, "_ref/"+mem)
		testutil.Git(t, src, "worktree", "add", "-q", "--detach", filepath.Join(dir, "_ref", mem), "origin/HEAD")
	}
	if len(refs) > 0 {
		ignore.WriteString("/_ref/\n")
	}
	testutil.WriteFile(t, filepath.Join(dir, ".vmono", "manifest.toml"), b.String())
	testutil.WriteFile(t, filepath.Join(dir, ".gitignore"), "# generated by vmono\n"+ignore.String())
	testutil.WriteFile(t, filepath.Join(dir, "AGENTS.md"), "<!-- vmono:begin -->\nold block\n<!-- vmono:end -->\n\nMY OWN NOTES\n")
	testutil.WriteFile(t, filepath.Join(dir, "CLAUDE.md"), "@AGENTS.md\n")
	testutil.WriteFile(t, filepath.Join(dir, ".claude", "settings.json"), "{}\n")
	testutil.Git(t, dir, "init", "-q", "-b", "main")
	testutil.Git(t, dir, "add", "-A")
	testutil.Git(t, dir, "commit", "-q", "-m", "vmono: create "+name)
	return dir
}

func TestListShowsLegacyPackagesAndLoadRefusesThem(t *testing.T) {
	c, env := newCore(t)
	a := env.NewSource(t, "alpha")
	writeLegacyPackage(t, c, "old", "vmono/old", []string{a}, nil)

	if _, err := c.Load("old"); !errors.Is(err, manifest.ErrLegacy) {
		t.Fatalf("Load of a legacy package = %v", err)
	}
	sums, err := c.List(true)
	if err != nil || len(sums) != 1 || !sums[0].Legacy || sums[0].Name != "old" {
		t.Fatalf("List = %+v, %v", sums, err)
	}
}

func TestDoctorReportsLegacyPackageWithoutChangingIt(t *testing.T) {
	c, env := newCore(t)
	a := env.NewSource(t, "alpha")
	dir := writeLegacyPackage(t, c, "old", "vmono/old", []string{a}, nil)

	res, err := c.Doctor(false)
	if err != nil {
		t.Fatal(err)
	}
	var legacy int
	for _, f := range res.Findings {
		switch f.Kind {
		case KindLegacyPackage:
			legacy++
			if f.Fixed {
				t.Error("report-only run must not fix")
			}
		case KindOrphanWorktree:
			t.Errorf("a legacy package's worktrees are not orphans: %+v", f)
		}
	}
	if legacy != 1 || res.Remaining() != 1 {
		t.Errorf("findings = %+v", res.Findings)
	}
	if _, err := os.Stat(filepath.Join(dir, "alpha", "README.md")); err != nil {
		t.Error("doctor without --fix must not move anything")
	}
}

func TestMigrateTurnsLegacyPackageIntoPackageWithOneSession(t *testing.T) {
	c, env := newCore(t)
	a := env.NewSource(t, "alpha")
	ref := env.NewSource(t, "contracts")
	dir := writeLegacyPackage(t, c, "old", "vmono/old", []string{a}, []string{ref})
	opened := time.Date(2026, 11, 10, 9, 0, 0, 0, time.UTC)
	c.Idx.RecordLaunch("old", "", "claude", opened)

	res, err := c.Doctor(true)
	if err != nil {
		t.Fatal(err)
	}
	var fixed bool
	for _, f := range res.Findings {
		if f.Kind == KindLegacyPackage && f.Fixed {
			fixed = true
		}
	}
	if !fixed || res.Remaining() != 0 {
		t.Fatalf("findings = %+v", res.Findings)
	}

	// Package: schema 2, text and history kept, no worktrees or generated files.
	p, err := c.Load("old")
	if err != nil {
		t.Fatal(err)
	}
	if p.M.Purpose != "Legacy purpose." || p.M.Schema != manifest.SchemaVersion || len(p.M.Members) != 2 {
		t.Errorf("package manifest = %+v", p.M)
	}
	for _, rel := range []string{"alpha", "_ref", "AGENTS.md", "CLAUDE.md", ".claude"} {
		if _, err := os.Stat(filepath.Join(dir, rel)); err == nil {
			t.Errorf("%s should have moved into the session", rel)
		}
	}
	log := subjects(t, dir)
	if len(log) != 2 || log[1] != "vmono: create old" || !strings.HasPrefix(log[0], "vmono: migrate to sessions") {
		t.Errorf("package history = %v", log)
	}
	if out := testutil.Git(t, dir, "status", "--porcelain"); out != "" {
		t.Errorf("package repo should be clean: %s", out)
	}

	// Session "main": keeps the legacy branch, worktrees repaired, text kept.
	s, err := c.LoadSession(p, "main")
	if err != nil {
		t.Fatal(err)
	}
	if s.S.Branch != "vmono/old" {
		t.Errorf("the migrated session must keep the legacy branch, got %q", s.S.Branch)
	}
	if br := gitx.CurrentBranch(filepath.Join(s.Dir, "alpha")); br != "vmono/old" {
		t.Errorf("alpha branch = %q", br)
	}
	if st, err := gitx.StatusOf(filepath.Join(s.Dir, "_ref", "contracts")); err != nil || !st.Detached {
		t.Errorf("reference member = %+v, %v", st, err)
	}
	list, _ := gitx.WorktreeList(a)
	var registered string
	for _, w := range list {
		if w.Branch == "vmono/old" {
			registered = w.Path
			if w.Prunable {
				t.Error("the moved worktree must not be stale")
			}
		}
	}
	if want := realPath(filepath.Join(s.Dir, "alpha")); realPath(registered) != want {
		t.Errorf("source registers the worktree at %q, want %q", registered, want)
	}
	agents, _ := os.ReadFile(filepath.Join(s.Dir, "AGENTS.md"))
	for _, want := range []string{"MY OWN NOTES", "Legacy purpose.", "session main", "vmono/old"} {
		if !strings.Contains(string(agents), want) {
			t.Errorf("AGENTS.md missing %q:\n%s", want, agents)
		}
	}
	if strings.Contains(string(agents), "old block") {
		t.Error("the stale generated block should have been replaced")
	}
	if _, err := os.Stat(filepath.Join(s.Dir, ".claude", "settings.json")); err != nil {
		t.Error("generated adapter files should move with the session")
	}
	if !gitx.HasCommits(s.Dir) || testutil.Git(t, s.Dir, "status", "--porcelain") != "" {
		t.Error("the session repo needs an initial commit and a clean tree")
	}
	if got := c.Idx.SessionOpened("old", "main"); !got.Equal(opened) {
		t.Errorf("last opened = %v, want %v", got, opened)
	}

	if again, _ := c.Doctor(false); again.Remaining() != 0 {
		t.Errorf("not clean after migration: %+v", again.Findings)
	}
	if res, err := c.Doctor(true); err != nil || len(res.Findings) > 1 {
		t.Errorf("a second --fix should find nothing but the index: %+v, %v", res.Findings, err)
	}
}

func TestMigrateAvoidsMemberNamedMain(t *testing.T) {
	c, env := newCore(t)
	// A member whose directory is called "main" would collide with the
	// session directory the migration wants to create.
	a := env.NewSource(t, "main")
	writeLegacyPackage(t, c, "clash", "vmono/clash", []string{a}, nil)

	if _, err := c.Doctor(true); err != nil {
		t.Fatal(err)
	}
	p, err := c.Load("clash")
	if err != nil {
		t.Fatal(err)
	}
	names, _ := p.Sessions()
	if strings.Join(names, ",") != "main-2" {
		t.Fatalf("sessions = %v", names)
	}
	if _, err := os.Stat(filepath.Join(p.Dir, "main-2", "main", "README.md")); err != nil {
		t.Errorf("worktree not moved under the session: %v", err)
	}
}

func TestMigrateToleratesAMissingWorktreeAndSource(t *testing.T) {
	c, env := newCore(t)
	a := env.NewSource(t, "alpha")
	b := env.NewSource(t, "beta")
	dir := writeLegacyPackage(t, c, "ragged", "vmono/ragged", []string{a, b}, nil)
	if err := os.RemoveAll(filepath.Join(dir, "alpha")); err != nil {
		t.Fatal(err)
	}
	if err := os.RemoveAll(b); err != nil {
		t.Fatal(err)
	}

	res, err := c.Doctor(true)
	if err != nil {
		t.Fatal(err)
	}
	p, err := c.Load("ragged")
	if err != nil {
		t.Fatalf("migration should still succeed: %v\n%+v", err, res.Findings)
	}
	s, err := c.LoadSession(p, "main")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(filepath.Join(s.Dir, "beta", "README.md")); err != nil {
		t.Error("a worktree whose source is gone still moves with the session")
	}
	// Alpha's directory was already missing, and doctor --fix recreated it
	// in the session in the same run.
	if _, err := os.Stat(filepath.Join(s.Dir, "alpha", "README.md")); err != nil {
		t.Errorf("missing worktree should be rebuilt in the session: %v", err)
	}
	var missingSource bool
	for _, f := range res.Findings {
		if f.Kind == KindMissingSource && f.Member == "beta" {
			missingSource = true
		}
	}
	if !missingSource {
		t.Errorf("the gone source should be reported: %+v", res.Findings)
	}
}

func TestLegacySessionNameSkipsTakenNames(t *testing.T) {
	dir := t.TempDir()
	m := &manifest.Manifest{Name: "n", Members: []manifest.Member{
		{Name: "main", Path: "main"}, {Name: "x", Path: "_ref/main-2", Mode: manifest.ModeReference},
	}}
	if got := legacySessionName(dir, m); got != "main-2" {
		t.Errorf("name = %q", got)
	}
	if err := os.Mkdir(filepath.Join(dir, "main-2"), 0o755); err != nil {
		t.Fatal(err)
	}
	if got := legacySessionName(dir, m); got != "main-3" {
		t.Errorf("name with main-2 on disk = %q", got)
	}
	if got := legacySessionName(dir, &manifest.Manifest{}); got != "main" {
		t.Errorf("free name = %q", got)
	}
}

// landingSession makes a session as it was when work landed on other branches:
// its file is of the old schema and its branch tracks the base.
func landingSession(t *testing.T, c *Core, env *testutil.Env) (*Session, string) {
	t.Helper()
	a := env.NewSource(t, "alpha")
	p := mustPackage(t, c, request("old", []string{a}, nil))
	s, err := c.CreateSession(p, "work", SessionOptions{Branch: "vmono/old/work"})
	if err != nil {
		t.Fatal(err)
	}
	testutil.Git(t, a, "branch", "--set-upstream-to=origin/main", "vmono/old/work")
	testutil.WriteFile(t, manifest.SessionPath(s.Dir), "schema  = 1\npackage = \"old\"\nname    = \"work\"\ncreated = 2026-11-16T09:00:00Z\nbranch  = \"vmono/old/work\"\nfinished = 2026-11-17T09:00:00Z\n\n[into]\nalpha = \"main\"\n")
	if s, err = c.LoadSession(p, "work"); err != nil {
		t.Fatal(err)
	}
	commitIn(t, filepath.Join(s.Dir, "alpha"), "work.txt")
	return s, a
}

// finding returns doctor's finding of a kind.
func finding(t *testing.T, res DoctorResult, kind string) (Finding, bool) {
	t.Helper()
	for _, f := range res.Findings {
		if f.Kind == kind {
			return f, true
		}
	}
	return Finding{}, false
}

func TestLandingSessionWorksUnconverted(t *testing.T) {
	c, env := newCore(t)
	s, _ := landingSession(t, c, env)
	main := sha(t, remoteOf(env, "alpha"), "refs/heads/main")
	if _, m := status(t, c, s, "alpha"); m.Publish != PublishLocal {
		t.Errorf("status = %+v", m)
	}
	res, err := c.Push(s, PushOptions{})
	if m := pushRow(t, res, "alpha"); err != nil || m.Status != PushPushed || m.Dest != "vmono/old/work" {
		t.Errorf("push = %+v, %v", m, err)
	}
	if sha(t, remoteOf(env, "alpha"), "refs/heads/main") != main {
		t.Error("main must not be pushed to")
	}
	if _, err := c.DeleteSession(s, DeleteOptions{}); err != nil {
		t.Error(err)
	}
}

func TestDoctorConvertsLandingSessions(t *testing.T) {
	c, env := newCore(t)
	s, a := landingSession(t, c, env)
	testutil.Git(t, a, "merge", "--quiet", "--ff-only", "vmono/old/work") // it landed, unpushed

	res, err := c.Doctor(false)
	f, ok := finding(t, res, KindLandingSession)
	if err != nil || !ok || f.Fixed || !strings.Contains(f.Message, "alpha:main is not on a remote") {
		t.Fatalf("finding = %+v, %v", f, err)
	}
	if loaded, _ := c.LoadSession(s.Pkg, "work"); loaded.S.Schema != manifest.LandingSessionSchema {
		t.Error("only --fix converts")
	}

	res, err = c.Doctor(true)
	if f, ok = finding(t, res, KindLandingSession); err != nil || !ok || !f.Fixed || !strings.Contains(f.Message, "push it by hand") {
		t.Fatalf("finding = %+v, %v", f, err)
	}
	loaded, err := c.LoadSession(s.Pkg, "work")
	if err != nil || loaded.S.Schema != manifest.SessionSchemaVersion || len(loaded.S.Into) != 0 || !loaded.S.Finished.IsZero() || loaded.BranchFor("alpha") != "vmono/old/work" {
		t.Errorf("session = %+v, %v", loaded.S, err)
	}
	if loaded.S.Members["alpha"].Created {
		t.Error("vmono cannot know it made the branch")
	}
	if tr, ok := gitx.UpstreamOf(a, "vmono/old/work"); ok {
		t.Errorf("upstream = %+v", tr)
	}
	if res, err = c.Doctor(true); err != nil {
		t.Fatal(err)
	}
	if f, ok := finding(t, res, KindLandingSession); ok {
		t.Errorf("a second run found %+v", f)
	}
}

func TestMigratedPackageBranchesTrackNothing(t *testing.T) {
	c, env := newCore(t)
	a := env.NewSource(t, "alpha")
	writeLegacyPackage(t, c, "old", "vmono/old", []string{a}, nil)
	if _, ok := gitx.UpstreamOf(a, "vmono/old"); !ok {
		t.Fatal("the fixture should track origin/main as it would have")
	}
	if _, err := c.Doctor(true); err != nil {
		t.Fatal(err)
	}
	if tr, ok := gitx.UpstreamOf(a, "vmono/old"); ok {
		t.Errorf("upstream = %+v", tr)
	}
}
